-- Do not edit by hand; change the mapping or the converter and regenerate.
-- Flow: SRT_ORDER_ID -> SRT_BEFORE_AGG_PDP -> AGG_BY_PRODUCT_DAY -> EXP_PRODUCT_METRICS -> PRODUCT_DAILY_PERFORMANCE
-- WARNING [PRODUCT_DAILY_PERFORMANCE]: probable crossed link: EXP_PRODUCT_METRICS.PERISHABLE_SALES_FLAG -> PRODUCT_DAILY_PERFORMANCE.MARGIN_PCT while EXP_PRODUCT_METRICS.MARGIN_PCT -> PRODUCT_DAILY_PERFORMANCE.PERISHABLE_SALES_FLAG; converted as linked
-- WARNING [PRODUCT_DAILY_PERFORMANCE]: probable crossed link: EXP_PRODUCT_METRICS.MARGIN_PCT -> PRODUCT_DAILY_PERFORMANCE.PERISHABLE_SALES_FLAG while EXP_PRODUCT_METRICS.PERISHABLE_SALES_FLAG -> PRODUCT_DAILY_PERFORMANCE.MARGIN_PCT; converted as linked

with

srt_order_id as (
    -- SRT_ORDER_ID (Sorter on order_id asc, order_item_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        order_id as order_id,
        order_item_id as order_item_id,
        product_id as product_id,
        customer_id as customer_id,
        customer_name as customer_name,
        location_id as location_id,
        location_name as location_name,
        region as region,
        ordered_at_day as ordered_at_day,
        product_name as product_name,
        product_type as product_type,
        product_price as product_price,
        is_food_item as is_food_item,
        is_drink_item as is_drink_item,
        item_revenue as item_revenue,
        item_cogs as item_cogs,
        item_gross_profit as item_gross_profit,
        item_gross_margin_pct as item_gross_margin_pct,
        item_tax_estimate as item_tax_estimate,
        item_total_estimate as item_total_estimate,
        has_perishable_supply as has_perishable_supply
    from {{ ref('int_fl_js_marts_enriched__exp_item_calculations') }}
),

srt_before_agg_pdp as (
    -- SRT_BEFORE_AGG_PDP (Sorter on product_id asc, ordered_at_day asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        product_id as product_id,
        product_name as product_name,
        product_type as product_type,
        ordered_at_day as ordered_at_day,
        order_item_id as order_item_id,
        item_revenue as item_revenue,
        item_cogs as item_cogs,
        item_gross_profit as item_gross_profit,
        has_perishable_supply as has_perishable_supply
    from srt_order_id
),

agg_by_product_day as (
    -- AGG_BY_PRODUCT_DAY (Aggregator) grouped by PRODUCT_ID, PRODUCT_NAME, PRODUCT_TYPE, ORDERED_AT_DAY
    select
        product_id as product_id,
        product_name as product_name,
        product_type as product_type,
        ordered_at_day as ordered_at_day,
        count(order_item_id) as units_sold,
        sum(item_revenue) as revenue,
        sum(item_cogs) as cogs,
        sum(item_gross_profit) as gross_profit,
        cast(max(has_perishable_supply) as integer) as perishable_sales_flag
    from srt_before_agg_pdp
    group by product_id, product_name, product_type, ordered_at_day
),

exp_product_metrics as (
    -- EXP_PRODUCT_METRICS (Expression)
    select
        product_id as product_id,
        product_name as product_name,
        product_type as product_type,
        ordered_at_day as ordered_at_day,
        units_sold as units_sold,
        revenue as revenue,
        cogs as cogs,
        gross_profit as gross_profit,
        cast(perishable_sales_flag as integer) as perishable_sales_flag,
        case when (revenue = 0) then 0 else (gross_profit / revenue) end as margin_pct
    from agg_by_product_day
),

final as (
    -- PRODUCT_DAILY_PERFORMANCE (Target PRODUCT_DAILY_PERFORMANCE): cast to the target column types
    select
        cast(product_id as varchar) as product_id,
        cast(product_name as varchar) as product_name,
        cast(product_type as varchar) as product_type,
        cast(ordered_at_day as timestamp) as ordered_at_day,
        cast(units_sold as decimal(15, 0)) as units_sold,
        cast(revenue as decimal(12, 2)) as revenue,
        cast(cogs as decimal(12, 2)) as cogs,
        cast(gross_profit as decimal(12, 2)) as gross_profit,
        cast(perishable_sales_flag as decimal(10, 4)) as margin_pct,
        cast(margin_pct as decimal(1, 0)) as perishable_sales_flag
    from exp_product_metrics
)

select * from final
